
"""Independent scoring of already-frozen choices."""

import argparse
import json
from pathlib import Path
import time

from common import DATA, PROTOCOL, check_data, score_choices


# Project code directory
ROOT = Path(__file__).resolve().parent


def main():
    total_started = time.perf_counter()

    parser = argparse.ArgumentParser(
        description=__doc__
    )

    # ===== Parameters: configure defaults here =====

    # Prediction results generated by predict.py
    parser.add_argument(
        '--predictions',
        type=Path,
        default=ROOT / 'runs' / 'test-predictions.json',
        help='Path to the prediction JSON file'
    )

    # Dataset split to score
    parser.add_argument(
        '--split',
        choices=('train', 'validation', 'test', 'audit'),
        default='test',
        help='Dataset split to score'
    )

    # Input data directory
    parser.add_argument(
        '--data-dir',
        type=Path,
        default=DATA,
        help='Directory containing the assignment data'
    )

    # Output scoring result
    parser.add_argument(
        '--output',
        type=Path,
        default=ROOT / 'runs' / 'test-score.json',
        help='Path to save the scoring result'
    )

    # Parse arguments; command-line values can override defaults
    args = parser.parse_args()

    tick = time.perf_counter()

    # ===== Check prediction file =====
    if not args.predictions.is_file():
        raise FileNotFoundError(
            f'Prediction file not found: {args.predictions}\n'
            'Please run predict.py first and check the predictions path.'
        )

    # ===== Load frozen predictions =====
    predictions = json.loads(
        args.predictions.read_text(encoding='utf-8')
    )

    # ===== Validate protocol and split =====
    if (
        predictions.get('protocol') != PROTOCOL
        or predictions.get('split') != args.split
    ):
        raise ValueError(
            'Prediction protocol or split does not match. '
            'Please ensure that --split matches the predictions file.'
        )

    # ===== Check dataset =====
    check_data(
        args.data_dir,
        (args.split,)
    )

    # ===== Calculate score =====
    result = {
        'protocol': PROTOCOL,
        'split': args.split,
        **score_choices(
            args.split,
            predictions['ids'],
            predictions['selected'],
            args.data_dir
        ),
        'scoring_seconds': time.perf_counter() - tick
    }

    # ===== Save scoring result =====
    args.output.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    args.output.write_text(
        json.dumps(result, indent=2) + '\n',
        encoding='utf-8'
    )

    # ===== Print result =====
    print(json.dumps(result, indent=2))

    print(
        f'Total elapsed time: '
        f'{time.perf_counter() - total_started:.2f} seconds'
    )


if __name__ == '__main__':
    main()
